//! Replays vectors/conformance.json (generated by tests/gen_conformance.py from the Python reference)
//! and demands exact agreement on supply, every balance, bond, stake, cap bucket and event after every step.
use serde_json::{json, Value};
use tremor::engine::*;

fn params(p: &Value, relief: &Value) -> Params {
    let g = |k: &str| p[k].as_u64().unwrap() as u128;
    Params { s0: g("s0"), min_mag_x10: g("min_mag_x10") as u32, base_ppm: g("base_ppm"), max_event_ppm: g("max_event_ppm"),
        cooldown_s: g("cooldown_s") as u64, week_cap_ppm: g("week_cap_ppm"), month_cap_ppm: g("month_cap_ppm"), bond: g("bond"),
        window_s: g("window_s") as u64, vote_s: g("vote_s") as u64, slash_pct: g("slash_pct"), quorum_ppm: g("quorum_ppm"),
        max_age_s: g("max_age_s") as u64, tap_amount: g("tap_amount"), relief: relief.as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect() }
}

fn nz(m: &std::collections::BTreeMap<String, u128>) -> Value {
    Value::Object(m.iter().filter(|(_, v)| **v != 0).map(|(k, v)| (k.clone(), json!(*v as u64))).collect())
}

fn snapshot(c: &Core) -> Value {
    let buckets: serde_json::Map<String, Value> = c.buckets.iter().filter(|(_, v)| **v != 0).map(|(k, v)| (k.to_string(), json!(*v as u64))).collect();
    let events: serde_json::Map<String, Value> = c.ev.iter().map(|(k, e)| {
        let w = match e.winner { Some(true) => "real", Some(false) => "not", None => "" };
        (k.clone(), json!([e.status.as_str(), e.minted as u64, e.pot as u64, e.win_left as u64, w, e.clipped]))
    }).collect();
    json!({"supply": c.supply as u64, "tok": nz(&c.tok), "bal": nz(&c.bal), "locked": nz(&c.locked),
           "buckets": buckets, "recent": c.recent, "tapped": c.tapped.iter().collect::<Vec<_>>(), "events": events})
}

#[test]
fn rust_matches_python_reference() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../vectors/conformance.json");
    let all: Vec<Value> = serde_json::from_str(&std::fs::read_to_string(path).expect("run `make conformance-vectors` first")).unwrap();
    assert!(all.len() >= 200, "need at least 200 scenarios");
    let (mut steps, mut mismatches) = (0, 0);
    for sc in &all {
        let mut c = Core::new(params(&sc["params"], &sc["relief"]), sc["launcher"].as_str().unwrap()).unwrap();
        for (i, st) in sc["steps"].as_array().unwrap().iter().enumerate() {
            let a = st["args"].as_array().unwrap();
            let s = |k: usize| a[k].as_str().unwrap().to_string();
            let n = |k: usize| a[k].as_i64().unwrap();
            let now = st["now"].as_u64().unwrap();
            let ok = match st["op"].as_str().unwrap() {
                "transfer" => c.ft_transfer(&s(0), &s(1), n(2) as u128).is_ok(),
                "deposit" => c.deposit_bond(&s(0), n(1) as u128).is_ok(),
                "withdraw" => c.withdraw_bond(&s(0), n(1) as u128).is_ok(),
                // a negative origin (impossible on chain) is treated as a rejection, as Python rejects "too old"/"future"
                "report" => n(3) >= 0 && c.report_event(&s(0), &s(1), n(2) as u32, n(3) as u64, now).is_ok(),
                "challenge" => c.challenge(&s(0), &s(1), now).is_ok(),
                "vote" => c.vote(&s(0), &s(1), match a[2].as_str().unwrap() { "real" => Some(true), "not" => Some(false), _ => None }, n(3) as u128, now).is_ok(),
                "finalize" => c.finalize(&s(0), now).is_ok(),
                "claim" => c.claim_vote(&s(0), &s(1)).is_ok(),
                "tap" => c.tap(&s(0), "pool").is_ok(),
                other => panic!("unknown op {other}"),
            };
            c.check_invariants();
            steps += 1;
            if ok != st["ok"].as_bool().unwrap() || snapshot(&c) != st["snap"] {
                mismatches += 1;
                if mismatches <= 3 { eprintln!("MISMATCH seed {} step {} op {} ok(rust)={} ok(py)={}", sc["seed"], i, st["op"], ok, st["ok"]); }
            }
        }
    }
    eprintln!("conformance: {} scenarios, {} steps, {} mismatches", all.len(), steps, mismatches);
    assert_eq!(mismatches, 0);
}

#[test]
fn golden_vector_one() {
    // GV-1 straight from RULES.md, independent of the Python reference.
    let p = Params { s0: 1_000_000_000_000, min_mag_x10: 60, base_ppm: 5000, max_event_ppm: 15000, cooldown_s: 86400, week_cap_ppm: 15000,
        month_cap_ppm: 50000, bond: 1_000_000_000, window_s: 86400, vote_s: 172800, slash_pct: 20, quorum_ppm: 2000, max_age_s: 5_184_000, tap_amount: 0,
        relief: (1..=5).map(|i| format!("r{i}")).collect() };
    let t0 = 20000 * DAY;
    let mut c = Core::new(p.clone(), "ada").unwrap();
    let run = |c: &mut Core, id: &str, mag: u32, origin: u64| {
        c.ev.insert(id.into(), Ev { mag_x10: mag, origin_s: origin, reporter: "x".into(), reported_at: origin, status: Status::Waiting, challenger: None,
            challenged_at: 0, votes: Default::default(), pot: 0, win_left: 0, winner: None, claimed: Default::default(), minted: 0, clipped: false });
        let gap = cooldown_gap(origin, &c.recent, p.cooldown_s);
        let (m, raw, clipped) = mint_amount(&c.p, c.supply, mag, gap, c.minted_last(origin, 7), c.minted_last(origin, 30));
        for (a, n) in c.p.relief.clone().iter().zip(split(m)) { *c.tok.entry(a.clone()).or_insert(0) += n; }
        c.supply += m; *c.buckets.entry(origin / DAY).or_insert(0) += m; c.recent.push(origin);
        c.ev.get_mut(id).unwrap().minted = m; c.ev.get_mut(id).unwrap().status = Status::Counted;
        (m, raw, clipped)
    };
    assert_eq!(run(&mut c, "E1", 60, t0), (5_000_000_000, 5_000_000_000, false));
    assert_eq!(run(&mut c, "E2", 70, t0 + 48 * 3600), (10_050_000_000, 10_050_000_000, false));
    let (m, raw, clipped) = run(&mut c, "E3", 60, t0 + 60 * 3600);
    assert_eq!((m, raw, clipped, c.supply), (175_750_000, 2_537_625_000, true, 1_015_225_750_000));
    assert_eq!(c.tok["r2"], 3_045_150_000);
}
